INSERT INTO "erp_ops"."source_import_file" ("file_id","source_root","relative_path","file_sha256","size_bytes","format_id","header","metadata") SELECT "file_id","source_root","relative_path","file_sha256","size_bytes","format_id","header","metadata" FROM jsonb_populate_recordset(NULL::"erp_ops"."source_import_file",convert_from(decode('','hex'),'UTF8')::jsonb) ON CONFLICT DO NOTHING;
