INSERT INTO "erp_ops"."source_import_run" ("run_id","importer_version","manifest_sha256","source_manifest","report") SELECT "run_id","importer_version","manifest_sha256","source_manifest","report" FROM jsonb_populate_recordset(NULL::"erp_ops"."source_import_run",convert_from(decode('','hex'),'UTF8')::jsonb) ON CONFLICT DO NOTHING;
DO $verify$ BEGIN IF EXISTS (SELECT 1 FROM jsonb_populate_recordset(NULL::"erp_ops"."source_import_run",convert_from(decode('','hex'),'UTF8')::jsonb) x LEFT JOIN "erp_ops"."source_import_run" t ON t."run_id"=x."run_id" WHERE t."run_id" IS NULL OR t."importer_version" IS DISTINCT FROM x."importer_version" OR t."manifest_sha256" IS DISTINCT FROM x."manifest_sha256" OR t."source_manifest" IS DISTINCT FROM x."source_manifest" OR t."report" IS DISTINCT FROM x."report") THEN RAISE EXCEPTION 'Release import conflicts with existing data'; END IF; END $verify$;
DO $$
DECLARE n integer; r record;
BEGIN
 SELECT count(*) INTO n FROM pg_namespace WHERE nspname IN ('finance','legal','production','rd','sales','analysis');
 IF n<>6 THEN RAISE EXCEPTION 'Expected 6 schemas, got %',n; END IF;
 SELECT count(*) INTO n FROM pg_tables WHERE schemaname IN ('finance','legal','production','rd','sales','analysis');
 IF n<>146 THEN RAISE EXCEPTION 'Expected 146 tables, got %',n; END IF;
 SELECT count(*) INTO n FROM pg_views WHERE schemaname IN ('finance','legal','production','rd','sales','analysis');
 IF n<>15 THEN RAISE EXCEPTION 'Expected 15 views, got %',n; END IF;
 SELECT count(*) INTO n FROM pg_constraint c JOIN pg_namespace s ON s.oid=c.connamespace
 WHERE s.nspname IN ('finance','legal','production','rd','sales','analysis') AND c.contype='f' AND c.convalidated;
 IF n<>475 THEN RAISE EXCEPTION 'Expected 475 validated foreign keys, got %',n; END IF;
 SELECT count(*) INTO n FROM pg_constraint c JOIN pg_namespace s ON s.oid=c.connamespace
 JOIN pg_attribute a ON a.attrelid=c.conrelid AND a.attnum=c.conkey[1]
 WHERE s.nspname IN ('finance','legal','production','rd','sales','analysis') AND c.contype='p'
 AND cardinality(c.conkey)=1 AND a.atttypid='text'::regtype;
 IF n<>146 THEN RAISE EXCEPTION 'Expected 146 single text primary keys, got %',n; END IF;
 FOR r IN SELECT schemaname,viewname FROM pg_views WHERE schemaname IN
 ('finance','legal','production','rd','sales','analysis','erp_ops') LOOP
  EXECUTE format('SELECT * FROM %I.%I LIMIT 0',r.schemaname,r.viewname);
 END LOOP;
 IF current_setting('server_encoding')<>'UTF8' THEN RAISE EXCEPTION 'Expected UTF8'; END IF;
 IF EXISTS(SELECT 1 FROM pg_constraint c JOIN pg_namespace n ON n.oid=c.connamespace
  WHERE n.nspname IN ('finance','legal','production','rd','sales','analysis') AND NOT c.convalidated) THEN
  RAISE EXCEPTION 'Unvalidated constraints';
 END IF;
END $$;

COMMIT;